def text_is_spam(text, request):
    # Based on a blog post by 'sciyoshi':
    # http://sciyoshi.com/blog/2008/aug/27/using-akismet-djangos-new-comments-framework/
    # This will return 'True' is the given text is deemed to be spam, or
    # False if it is not spam. If it cannot be checked for some reason, we
    # assume it isn't spam.
    try:
        from akismet import Akismet
    except ImportError:
        return False
    from django.contrib.sites.models import Site
    from django.core.exceptions import ImproperlyConfigured

    try:
        site = Site.objects.get_current()
    except ImproperlyConfigured:
        site = Site(domain="configure-django-sites.com")

    # see https://akismet.readthedocs.io/en/latest/overview.html#using-akismet

    apikey = None

    if hasattr(settings, "TYPEPAD_ANTISPAM_API_KEY"):
        apikey = settings.TYPEPAD_ANTISPAM_API_KEY
    elif hasattr(settings, "PYTHON_AKISMET_API_KEY"):
        # new env var expected by python-akismet package
        apikey = settings.PYTHON_AKISMET_API_KEY
    elif hasattr(settings, "AKISMET_API_KEY"):
        # deprecated, but kept for backward compatibility
        apikey = settings.AKISMET_API_KEY
    else:
        return False

    ak = Akismet(
        blog_url=f"http://{site.domain}/",
        key=apikey,
    )

    if hasattr(settings, "TYPEPAD_ANTISPAM_API_KEY"):
        ak.baseurl = "api.antispam.typepad.com/1.1/"

    if ak.verify_key():
        ak_data = {
            "user_ip": request.META.get("REMOTE_ADDR", "127.0.0.1"),
            "user_agent": request.headers.get("User-Agent", ""),
            "referrer": request.headers.get("Referer", ""),
            "comment_type": "comment",
            "comment_author": "",
        }

        return ak.comment_check(smart_str(text), data=ak_data)

    return False

def process_attachments(followup, attached_files):
    max_email_attachment_size = getattr(
        settings, "HELPDESK_MAX_EMAIL_ATTACHMENT_SIZE", 512000
    )
    attachments = []
    errors = set()

    for attached in attached_files:
        if attached.size:
            from helpdesk.models import FollowUpAttachment

            filename = smart_str(attached.name)
            att = FollowUpAttachment(
                followup=followup,
                file=attached,
                filename=filename,
                mime_type=attached.content_type
                or mimetypes.guess_type(filename, strict=False)[0]
                or "application/octet-stream",
                size=attached.size,
            )
            try:
                att.full_clean()
            except ValidationError as e:
                errors.add(e)
            else:
                att.save()

                if attached.size < max_email_attachment_size:
                    # Only files smaller than 512kb (or as defined in
                    # settings.HELPDESK_MAX_EMAIL_ATTACHMENT_SIZE) are sent via
                    # email.
                    attachments.append([filename, att.file])

    if errors:
        raise ValidationError(list(errors))

    return attachments

def format_time_spent(time_spent):
    """Format time_spent attribute to "[H]HHh:MMm" text string to be align in
    all graphical outputs
    """
    if time_spent:
        time_spent = f"{int(time_spent.total_seconds()) // 3600:02d}h:{int(time_spent.total_seconds()) % 3600 // 60:02d}m"
    else:
        time_spent = ""
    return time_spent

def convert_value(value):
    """Convert date/time data type to known fixed format string"""
    if type(value) is datetime:
        return value.strftime(helpdesk_settings.CUSTOMFIELD_DATETIME_FORMAT)
    elif type(value) is date:
        return value.strftime(helpdesk_settings.CUSTOMFIELD_DATE_FORMAT)
    elif type(value) is time:
        return value.strftime(helpdesk_settings.CUSTOMFIELD_TIME_FORMAT)
    else:
        return value

def get_assignable_users(filter_staff: bool) -> QuerySet:
    users = User.objects.filter(is_active=True)

    if filter_staff:
        users = users.filter(is_staff=True)

    return users.order_by(User.USERNAME_FIELD)

def handle(self, *args, **options):
    days = options["days"]
    occurrences = options["occurrences"]
    verbose = options["exclude_verbosely"]
    queue_slugs = options["queues"]

    if not (days and occurrences):
        raise CommandError("One or more occurrences must be specified.")

    queues = []
    if queue_slugs is not None:
        queues = Queue.objects.filter(slug__in=queue_slugs)

    for day_name in days:
        day = day_names[day_name]
        workdate = timezone.now().date()
        i = 0
        while i < occurrences:
            if day == workdate.weekday():
                if EscalationExclusion.objects.filter(date=workdate).count() == 0:
                    esc = EscalationExclusion.objects.create(
                        name=f"Auto Exclusion for {day_name}", date=workdate
                    )

                    if verbose:
                        self.stdout.write(
                            f"Created exclusion for {day_name} {workdate}"
                        )

                    for q in queues:
                        esc.queues.add(q)
                        if verbose:
                            self.stdout.write(f"  - for queue {q}")

                i += 1
            workdate += timedelta(days=1)

def handle(self, *args, **options):
    queue_slugs = options["queues"]

    if queue_slugs is not None:
        queues = Queue.objects.filter(slug__in=queue_slugs)
    else:
        queues = Queue.objects.all()

    # Create permissions for the queues, which may be all or not
    for q in queues:
        self.stdout.write(f"Preparing Queue {q} [{q.slug}]")

        if q.permission_name:
            self.stdout.write(
                f"  .. already has `permission_name={q.permission_name}`"
            )
            basename = q.permission_name[9:]
        else:
            basename = q.generate_permission_name()
            self.stdout.write(
                f"  .. generated `permission_name={q.permission_name}`"
            )
            q.save()

        self.stdout.write(f"  .. checking permission codename `{basename}`")

        try:
            Permission.objects.create(
                name=_("Permission for queue: ") + q.title,
                content_type=ContentType.objects.get(model="queue"),
                codename=basename,
            )
        except IntegrityError:
            self.stdout.write("  .. permission already existed, skipping")

def handle(self, *args, **options):
