def get_queryset(self):
    # submitter_email and User.email are both unverified and both default to
    # an empty value, so matching one against the other made every account
    # without an address the submitter of every ticket without one. An
    # address identifies nobody until it is non-empty on both sides.
    email = self.request.user.email
    if not email:
        return Ticket.objects.none()
    tickets = (
        Ticket.objects.filter(submitter_email=email)
        .exclude(submitter_email="")
        .order_by("-created")
    )
    for ticket in tickets:
        ticket.set_custom_field_values()
    return tickets

def get_queryset(self):
    tickets = HelpdeskUser(self.request.user).accessible_tickets()

    # filter by status
    status = self.request.query_params.get("status", None)
    if status:
        statuses = status.split(",") if status else []
        status_choices = helpdesk_settings.TICKET_STATUS_CHOICES
        number_statuses = []
        for status in statuses:
            for choice in status_choices:
                if str(choice[0]) == status:
                    number_statuses.append(choice[0])
        if number_statuses:
            tickets = tickets.filter(status__in=number_statuses)

    for ticket in tickets:
        ticket.set_custom_field_values()
    return tickets

